// Copy buttons (.btn-copy with data-clipboard-text) generated by the IG Publisher.
// Replaces base2's clipboard-btn.js, which needs Bootstrap's tooltip plugin:
// the message is shown with CSS (data-copy-msg, see _sass/custom/custom.scss).

(function() {
  if (typeof ClipboardJS === 'undefined') return;

  function flash(button, message) {
    button.setAttribute('data-copy-msg', message);
    clearTimeout(button.copyTimer);
    button.copyTimer = setTimeout(function() {
      button.removeAttribute('data-copy-msg');
    }, 1000);
  }

  var clipboard = new ClipboardJS('.btn-copy');

  clipboard.on('success', function(e) {
    flash(e.trigger, 'Copied!');
    e.clearSelection();
  });

  clipboard.on('error', function(e) {
    flash(e.trigger, 'Failed - copy manually');
  });
})();
